","/* ============================================================
 Employee Assigned Training Dashboard — Horizon Design System
 ============================================================ */

/* ---- Alias layer ---- */
:root {
 --snx-color-surface: rgb(var(--now-color_background--primary, 255, 255, 255));
 --snx-color-surface-alt: rgb(var(--now-color_background--secondary, 245, 246, 247));
 --snx-color-surface-header: rgb(var(--now-color_background--tertiary, 226, 229, 231));
 --snx-color-border: rgb(var(--now-container--border-color, 207, 213, 215));
 --snx-color-text: rgb(var(--now-color_text--primary, 16, 23, 26));
 --snx-color-text-secondary: rgb(var(--now-color_text--secondary, 75, 85, 89));
 --snx-color-primary: rgb(var(--now-actionable--primary--background-color, 0, 128, 163));
 --snx-color-primary-hover: rgb(var(--now-actionable--primary--background-color--hover, 0, 138, 173));
 --snx-color-on-primary: rgb(var(--now-actionable_label--primary--color, 255, 255, 255));
 --snx-color-focus: rgb(var(--now-color_focus-ring, 53, 147, 37));
 --snx-radius-container: var(--now-container--border-radius, 8px);
 --snx-radius-input: var(--now-form-control-input--primary--border-radius, 2px);
 --snx-font: var(--now-font-family, "Lato", Arial, sans-serif);
 --snx-space-xs: var(--now-static-space--xs, 0.25rem);
 --snx-space-sm: var(--now-static-space--sm, 0.5rem);
 --snx-space-md: var(--now-static-space--md, 0.75rem);
 --snx-space-lg: var(--now-static-space--lg, 1rem);
 --snx-space-xl: var(--now-static-space--xl, 1.5rem);
 --snx-space-xxl: var(--now-static-space--xxl, 2rem);
}

/* ---- Reset ---- */
*,
*::before,
*::after {
 box-sizing: border-box;
}

body {
 margin: 0;
 padding: 0;
 font-family: var(--snx-font);
 background-color: var(--snx-color-surface-alt);
 color: var(--snx-color-text);
 line-height: var(--now-static-line-height, 1.25);
}

h1, h2, h3, p {
 margin: 0;
}

/* ---- Dashboard layout ---- */
.dashboard {
 max-width: 1200px;
 margin: 0 auto;
 padding: var(--snx-space-xl);
 display: flex;
 flex-direction: column;
 gap: var(--snx-space-xl);
}

/* ---- Header ---- */
.dashboard-header {
 display: flex;
 flex-direction: column;
 gap: var(--snx-space-xs);
}

.dashboard-title {
 font-size: var(--now-static-font-size--xl, 1.5rem);
 font-weight: 700;
 color: var(--snx-color-text);
}

.dashboard-subtitle {
 font-size: var(--now-static-font-size--md, 1rem);
 color: var(--snx-color-text-secondary);
}

/* ---- Filter bar ---- */
.filter-bar {
 display: flex;
 flex-wrap: wrap;
 align-items: flex-end;
 gap: var(--snx-space-lg);
 padding: var(--snx-space-xl);
 background-color: var(--snx-color-surface);
 border: 1px solid var(--snx-color-border);
 border-radius: var(--snx-radius-container);
 box-shadow: var(--now-static-drop-shadow--sm);
}

.filter-group {
 display: flex;
 flex-direction: column;
 gap: var(--snx-space-xs);
 flex: 1 1 200px;
 min-width: 180px;
}

.filter-label {
 font-weight: var(--now-form-control_label--primary--font-weight, 600);
 font-size: 0.875rem;
 color: rgb(var(--now-form-control_label--primary--color, 16, 23, 26));
}

.filter-input,
.filter-select {
 height: calc(1rem + var(--now-form-field--scale-size-block, 1) * 2rem / 2);
 padding: 0 var(--snx-space-md);
 border: 1px solid rgb(var(--now-form-control-input--primary--border-color, 115, 127, 132));
 border-radius: var(--snx-radius-input);
 background-color: rgb(var(--now-input--background-color, 255, 255, 255));
 color: var(--snx-color-text);
 font-family: var(--snx-font);
 font-size: var(--now-static-font-size--md, 1rem);
 transition: border-color 100ms linear;
 width: 100%;
}

.filter-input::placeholder {
 color: var(--snx-color-text-secondary);
 opacity: 0.7;
}

.filter-input:focus,
.filter-select:focus {
 outline: none;
 border-color: rgb(var(--now-form-control-input--primary--border-color--focus, 53, 147, 37));
 box-shadow: inset 0 0 0 1px rgb(var(--now-form-control_focus-ring--primary--color, 53, 147, 37));
}

.filter-select {
 appearance: auto;
 cursor: pointer;
}

.filter-actions {
 display: flex;
 align-items: flex-end;
 gap: var(--snx-space-sm);
 padding-bottom: 1px;
}

/* ---- Table ---- */
.table-wrapper {
 overflow-x: auto;
 border: 1px solid var(--snx-color-border);
 border-radius: var(--snx-radius-container);
 background-color: var(--snx-color-surface);
 box-shadow: var(--now-static-drop-shadow--sm);
}

.training-table {
 width: 100%;
 border-collapse: collapse;
}

.training-table th,
.training-table td {
 padding: var(--snx-space-md) var(--snx-space-lg);
 text-align: left;
 border-bottom: 1px solid var(--snx-color-border);
 white-space: nowrap;
}

.training-table thead {
 background-color: var(--snx-color-surface-header);
}

.training-table thead th {
 font-weight: 600;
 font-size: 0.875rem;
 color: var(--snx-color-text);
 text-transform: uppercase;
 letter-spacing: 0.03em;
}

.training-table tbody tr {
 background-color: var(--snx-color-surface);
 transition: background-color 100ms linear;
}

.training-table tbody tr:hover {
 background-color: var(--snx-color-surface-alt);
}

.training-table tbody tr:last-child td {
 border-bottom: none;
}

.cell--name {
 font-weight: 600;
 color: var(--snx-color-text);
}

.row--complete {
 opacity: 0.7;
}

.done-label {
 display: inline-flex;
 align-items: center;
 gap: var(--snx-space-xs);
 font-weight: 600;
 color: rgb(var(--now-indicator--primary_positive--background-color, 62, 134, 0));
 font-size: 0.875rem;
}

/* ---- Status badges ---- */
.badge {
 display: inline-flex;
 align-items: center;
 padding: 0.125rem 0.625rem;
 border-radius: 999px;
 font-size: 0.75rem;
 font-weight: 600;
 letter-spacing: 0.02em;
 white-space: nowrap;
}

.badge--info {
 background-color: rgb(var(--now-indicator--primary_info--background-color, 0, 128, 163));
 color: rgb(var(--now-indicator_label--primary_info--color, 255, 255, 255));
 border: 1px solid rgb(var(--now-indicator--primary_info--border-color, 0, 100, 128));
}

.badge--warning {
 background-color: rgb(var(--now-indicator--primary_warning--background-color, 204, 148, 30));
 color: rgb(var(--now-indicator_label--primary_warning--color, 255, 255, 255));
 border: 1px solid rgb(var(--now-indicator--primary_warning--border-color, 170, 120, 10));
}

.badge--positive {
 background-color: rgb(var(--now-indicator--primary_positive--background-color, 62, 134, 0));
 color: rgb(var(--now-indicator_label--primary_positive--color, 255, 255, 255));
 border: 1px solid rgb(var(--now-indicator--primary_positive--border-color, 48, 103, 0));
}

.badge--critical {
 background-color: rgb(var(--now-indicator--primary_critical--background-color, 229, 34, 57));
 color: rgb(var(--now-indicator_label--primary_critical--color, 255, 255, 255));
 border: 1px solid rgb(var(--now-indicator--primary_critical--border-color, 180, 20, 40));
}

/* ---- Loading / Error / Empty states ---- */
.state-container {
 display: flex;
 flex-direction: column;
 align-items: center;
 justify-content: center;
 gap: var(--snx-space-md);
 padding: var(--snx-space-xxl) var(--snx-space-lg);
 background-color: var(--snx-color-surface);
 border: 1px solid var(--snx-color-border);
 border-radius: var(--snx-radius-container);
 min-height: 200px;
}

.state-container--error {
 border-color: rgb(var(--now-indicator--primary_critical--border-color, 229, 34, 57));
}

.state-title {
 font-size: var(--now-static-font-size--lg, 1.25rem);
 font-weight: 600;
 color: var(--snx-color-text);
}

.state-text {
 font-size: var(--now-static-font-size--md, 1rem);
 color: var(--snx-color-text-secondary);
}

.state-text--error {
 color: rgb(var(--now-indicator--primary_critical--background-color, 229, 34, 57));
}

/* ---- Spinner ---- */
.spinner {
 border: 3px solid rgba(var(--now-loading_indicator--primary--color, 0, 128, 163), 0.2);
 border-top-color: rgb(var(--now-loading_indicator--primary--color, 0, 128, 163));
 border-radius: 50%;
 width: 2rem;
 height: 2rem;
 animation: spin 0.8s linear infinite;
}

@keyframes spin {
 100% {
 transform: rotate(360deg);
 }
}

/* ---- Responsive ---- */
@media (max-width: 768px) {
 .dashboard {
 padding: var(--snx-space-lg);
 }

 .filter-bar {
 flex-direction: column;
 align-items: stretch;
 }

 .filter-group {
 flex: 1 1 100%;
 }

 .filter-actions {
 justify-content: stretch;
 width: 100%;
 }

 .training-table th,
 .training-table td {
 padding: var(--snx-space-sm) var(--snx-space-md);
 font-size: 0.875rem;
 }
}

/* ---- Content area ---- */
.content-area {
 display: flex;
 flex-direction: column;
}
","export default function insertStyle(css, tagName = "style") {
 if (!css || typeof window === "undefined")
 return;
 if (tagName === "style") {
 const style = document.createElement("style");
 style.setAttribute("type", "text/css");
 style.innerHTML = css;
 document.head.appendChild(style);
 }
 else if (tagName === "link") {
 const link = document.createElement("link");
 link.setAttribute("rel", "stylesheet");
 link.setAttribute("href", css);
 document.head.appendChild(link);
 }
 return css;
}","import React, { useState, useEffect, useCallback } from "react";
import ReactDOM from "react-dom/client";
import { Button } from "@servicenow/react-components/Button";
import "./styles.css";

var TABLE = "x_2182380_pwcnow_employee_training";
var API_BASE = "/api/now/table/" + TABLE;
var FIELDS =
 "sys_id,u_training_name,u_due_date,u_completion_date,u_status,number";

function getHeaders() {
 return {
 "Content-Type": "application/json",
 Accept: "application/json",
 "X-UserToken": window.g_ck,
 };
}

function display(field) {
 return (field && field.display_value) || "";
}

function val(field) {
 return (field && field.value) || "";
}

function StatusBadge(props) {
 var status = props.status;
 var map = {
 assigned: { label: "Assigned", cls: "badge--info" },
 in_progress: { label: "In Progress", cls: "badge--warning" },
 complete: { label: "Complete", cls: "badge--positive" },
 overdue: { label: "Overdue", cls: "badge--critical" },
 };
 var s = map[status] || { label: status || "Unknown", cls: "" };
 return <span className={"badge " + s.cls}>{s.label}</span>;
}

function LoadingState() {
 return (
 <div className="state-container">
 <div className="spinner" />
 <p className="state-text">Loading your trainings…</p>
 </div>
 );
}

function ErrorState(props) {
 return (
 <div className="state-container state-container--error">
 <p className="state-text state-text--error">{props.message}</p>
 <Button label="Retry" variant="secondary" onClick={props.onRetry} />
 </div>
 );
}

function EmptyState() {
 return (
 <div className="state-container">
 <p className="state-title">No trainings found</p>
 <p className="state-text">
 Adjust your filters or check back later for new assignments.
 </p>
 </div>
 );
}

function FilterBar(props) {
 return (
 <section className="filter-bar" aria-label="Filter trainings">
 <div className="filter-group">
 <label className="filter-label" htmlFor="filter-name">
 Training Name
 </label>
 <input
 id="filter-name"
 className="filter-input"
 type="text"
 placeholder="Search by name…"
 value={props.nameFilter}
 onChange={function (e) {
 props.onNameChange(e.target.value);
 }}
 />
 </div>
 <div className="filter-group">
 <label className="filter-label" htmlFor="filter-status">
 Status
 </label>
 <select
 id="filter-status"
 className="filter-select"
 value={props.statusFilter}
 onChange={function (e) {
 props.onStatusChange(e.target.value);
 }}
 >
 <option value="">All Statuses</option>
 <option value="assigned">Assigned</option>
 <option value="in_progress">In Progress</option>
 <option value="complete">Complete</option>
 <option value="overdue">Overdue</option>
 </select>
 </div>
 <div className="filter-group">
 <label className="filter-label" htmlFor="filter-date">
 Due Date (on or before)
 </label>
 <input
 id="filter-date"
 className="filter-input"
 type="date"
 value={props.dueDateFilter}
 onChange={function (e) {
 props.onDueDateChange(e.target.value);
 }}
 />
 </div>
 <div className="filter-actions">
 <Button label="Apply Filters" variant="primary" onClick={props.onApply} />
 <Button label="Clear" variant="secondary" onClick={props.onClear} />
 </div>
 </section>
 );
}

function TrainingTable(props) {
 var trainings = props.trainings;
 var completing = props.completing;
 var onComplete = props.onComplete;

 return (
 <div className="table-wrapper">
 <table className="training-table">
 <thead>
 <tr>
 <th>Training Name</th>
 <th>Due Date</th>
 <th>Completion Date</th>
 <th>Status</th>
 <th>Action</th>
 </tr>
 </thead>
 <tbody>
 {trainings.map(function (t) {
 var sysId = val(t.sys_id);
 var status = val(t.u_status);
 var isComplete = status === "complete";
 var isCompleting = completing === sysId;
 return (
 <tr key={sysId} className={isComplete ? "row--complete" : ""}>
 <td className="cell--name">{display(t.u_training_name)}</td>
 <td>{display(t.u_due_date) || "—"}</td>
 <td>{display(t.u_completion_date) || "—"}</td>
 <td>
 <StatusBadge status={status} />
 </td>
 <td>
 {isComplete ? (
 <span className="done-label">✓ Done</span>
 ) : (
 <Button
 label={isCompleting ? "Completing…" : "Complete"}
 variant="primary"
 disabled={isCompleting}
 onClick={function () {
 onComplete(sysId);
 }}
 />
 )}
 </td>
 </tr>
 );
 })}
 </tbody>
 </table>
 </div>
 );
}

function App() {
 var trainingsState = useState([]);
 var trainings = trainingsState[0];
 var setTrainings = trainingsState[1];

 var loadingState = useState(true);
 var loading = loadingState[0];
 var setLoading = loadingState[1];

 var errorState = useState(null);
 var error = errorState[0];
 var setError = errorState[1];

 var nameState = useState("");
 var nameFilter = nameState[0];
 var setNameFilter = nameState[1];

 var statusState = useState("");
 var statusFilter = statusState[0];
 var setStatusFilter = statusState[1];

 var dateState = useState("");
 var dueDateFilter = dateState[0];
 var setDueDateFilter = dateState[1];

 var completingState = useState(null);
 var completing = completingState[0];
 var setCompleting = completingState[1];

 var fetchTrainings = useCallback(
 function () {
 setLoading(true);
 setError(null);

 var userId = (window.NOW && window.NOW.user_id) || "";
 if (!userId) {
 setError("Unable to determine current user.");
 setLoading(false);
 return;
 }

 var query = "u_employee=" + userId;
 if (nameFilter) query += "^u_training_nameLIKE" + nameFilter;
 if (statusFilter) query += "^u_status=" + statusFilter;
 if (dueDateFilter) query += "^u_due_date<=" + dueDateFilter;

 var url =
 API_BASE +
 "?sysparm_query=" +
 encodeURIComponent(query) +
 "&sysparm_display_value=all" +
 "&sysparm_fields=" +
 FIELDS;

 fetch(url, { headers: getHeaders() })
 .then(function (resp) {
 if (!resp.ok)
 throw new Error("Failed to load trainings (" + resp.status + ")");
 return resp.json();
 })
 .then(function (data) {
 setTrainings(data.result || []);
 })
 .catch(function (err) {
 setError(err.message);
 })
 .finally(function () {
 setLoading(false);
 });
 },
 [nameFilter, statusFilter, dueDateFilter]
 );

 useEffect(function () {
 fetchTrainings();
 }, []);

 var handleComplete = function (sysId) {
 setCompleting(sysId);
 var today = new Date().toISOString().split("T")[0];

 fetch(API_BASE + "/" + sysId, {
 method: "PATCH",
 headers: getHeaders(),
 body: JSON.stringify({
 u_status: "complete",
 u_completion_date: today,
 }),
 })
 .then(function (resp) {
 if (!resp.ok)
 throw new Error("Failed to complete training (" + resp.status + ")");
 return fetchTrainings();
 })
 .catch(function (err) {
 setError(err.message);
 })
 .finally(function () {
 setCompleting(null);
 });
 };

 var clearFilters = function () {
 setNameFilter("");
 setStatusFilter("");
 setDueDateFilter("");
 };

 return (
 <div className="dashboard">
 <header className="dashboard-header">
 <h1 className="dashboard-title">My Assigned Trainings</h1>
 <p className="dashboard-subtitle">
 Track and complete your assigned training courses
 </p>
 </header>

 <FilterBar
 nameFilter={nameFilter}
 statusFilter={statusFilter}
 dueDateFilter={dueDateFilter}
 onNameChange={setNameFilter}
 onStatusChange={setStatusFilter}
 onDueDateChange={setDueDateFilter}
 onApply={fetchTrainings}
 onClear={clearFilters}
 />

 <section className="content-area">
 {loading && <LoadingState />}
 {!loading && error && (
 <ErrorState message={error} onRetry={fetchTrainings} />
 )}
 {!loading && !error && trainings.length === 0 && <EmptyState />}
 {!loading && !error && trainings.length > 0 && (
 <TrainingTable
 trainings={trainings}
 completing={completing}
 onComplete={handleComplete}
 />
 )}
 </section>
 </div>
 );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);
